WITH recent_orders AS (SELECT *, amount - discount amount_minus_discount FROM orders WHERE amount > 1250), orders_stats AS (SELECT CASE WHEN shipping_fee >= 42 THEN 'high' WHEN shipping_fee >= 19 THEN 'mid' ELSE 'low' END shipping_fee_bucket, MAX(order_date) last_order_date, COUNT(*) cnt FROM recent_orders GROUP BY CASE WHEN shipping_fee >= 42 THEN 'high' WHEN shipping_fee >= 19 THEN 'mid' ELSE 'low' END) SELECT shipping_fee_bucket, cnt FROM orders_stats WHERE cnt < 5 ORDER BY cnt DESC
